import { createElement, type FC, type ReactNode, useState } from "react";
import {
	formatValue,
	type ValueFormat,
} from "@/lib/json-renderer/format-value";
import { cn, FILLED_BOX } from "@/lib/utils";
import { isExternalHttpUrl } from "../_shared/view";
import { McpMarkdownText } from "./markdown-view";

type UnknownRecord = Record<string, unknown>;

export type McpJsonNode = UnknownRecord & {
	type: string;
	children?: McpJsonNode[];
};

type RendererAction = (...args: unknown[]) => unknown;

interface RenderContext {
	data: UnknownRecord;
	actions?: Record<string, RendererAction>;
	openLink: (href: string) => void;
}

function isRecord(value: unknown): value is UnknownRecord {
	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function getValueByPath(value: UnknownRecord, path: string): unknown {
	const parts = path.replace(/\[(\d+)\]/g, ".$1").split(".");
	let current: unknown = value;
	for (const part of parts) {
		if (!isRecord(current) && !Array.isArray(current)) return undefined;
		current = (current as UnknownRecord)[part];
	}
	return current;
}

function stringify(value: unknown): string {
	try {
		return JSON.stringify(value, null, 2);
	} catch {
		return String(value);
	}
}

function humanize(value: string): string {
	return value
		.replace(/[_-]+/g, " ")
		.replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function resolveProp(value: unknown, context: RenderContext): unknown {
	if (typeof value !== "string") return value;
	if (value.startsWith("@")) return context.actions?.[value.slice(1)];
	const exact = value.match(/^\{\{(.+?)\}\}$/);
	if (exact) return getValueByPath(context.data, exact[1].trim());
	return value.replace(/\{\{(.+?)\}\}/g, (_match, path: string) => {
		const resolved = getValueByPath(context.data, path.trim());
		return resolved === undefined ? "" : String(resolved);
	});
}

function resolvedProps(
	node: McpJsonNode,
	context: RenderContext,
): UnknownRecord {
	const raw: UnknownRecord = {};
	for (const [key, value] of Object.entries(node)) {
		if (
			!["type", "children", "props", "path", "fallback", "key"].includes(key)
		) {
			raw[key] = value;
		}
	}
	if (isRecord(node.props)) Object.assign(raw, node.props);
	const resolved: UnknownRecord = {};
	for (const [key, value] of Object.entries(raw)) {
		const next = resolveProp(value, context);
		if (/^on[A-Z]/.test(key) && typeof next !== "function") continue;
		resolved[key] = next;
	}
	return resolved;
}

function domProps(props: UnknownRecord): UnknownRecord {
	const result: UnknownRecord = {};
	for (const key of [
		"className",
		"style",
		"title",
		"id",
		"role",
		"colSpan",
		"rowSpan",
		"onClick",
	]) {
		if (props[key] !== undefined) result[key] = props[key];
	}
	for (const [key, value] of Object.entries(props)) {
		if (key.startsWith("aria-") || key.startsWith("data-")) result[key] = value;
	}
	return result;
}

function scalar(value: unknown): ReactNode {
	if (value === null || value === undefined) return "";
	if (typeof value === "string" || typeof value === "number") return value;
	if (typeof value === "boolean") return value ? "Yes" : "No";
	return (
		<pre className="overflow-auto whitespace-pre-wrap text-xs">
			{stringify(value)}
		</pre>
	);
}

function normalizePoints(
	value: unknown,
	labelField = "label",
	valueField = "value",
): Array<{ key: string; label: string; value: number }> {
	if (!Array.isArray(value)) return [];
	return value
		.map((item, index) => {
			if (typeof item === "number")
				return {
					key: `${index + 1}:${item}`,
					label: String(index + 1),
					value: item,
				};
			if (!isRecord(item)) return null;
			const label = String(item[labelField] ?? item.name ?? index + 1);
			const pointValue = Number(item[valueField] ?? 0);
			return {
				key: `${label}:${pointValue}:${index}`,
				label,
				value: pointValue,
			};
		})
		.filter((item): item is { key: string; label: string; value: number } =>
			Boolean(item && Number.isFinite(item.value)),
		);
}

const CHART_COLORS = ["#6366f1", "#8b5cf6", "#d946ef", "#ec4899", "#f43f5e"];
const PLATFORM_COLORS: Record<string, string> = {
	reddit: "#FF4500",
	github: "#333333",
	trustpilot: "#00B67A",
	hackernews: "#FF6600",
	x: "#1DA1F2",
	ios_appstore: "#007AFF",
	google_play: "#34A853",
	glassdoor: "#0CAA41",
	g2: "#FF492C",
	capterra: "#FF6B35",
	gmaps: "#4285F4",
};

function seriesColor(key: string, index: number): string {
	return (
		PLATFORM_COLORS[key.toLowerCase()] ??
		CHART_COLORS[index % CHART_COLORS.length]
	);
}

const CartesianChart: FC<{
	data: unknown;
	kind: "bar" | "line" | "area";
	labelField?: string;
	valueField?: string;
	xLabel?: string;
	yLabel?: string;
	height?: number;
}> = ({ data, kind, labelField, valueField, xLabel, yLabel, height }) => {
	const points = normalizePoints(data, labelField, valueField);
	if (points.length === 0)
		return <p className="text-muted-foreground text-xs">No chart data.</p>;
	const width = 600;
	const chartHeight = Math.max(120, Number(height) || 300);
	const pad = { left: 44, right: 14, top: 14, bottom: 38 };
	const innerWidth = width - pad.left - pad.right;
	const innerHeight = chartHeight - pad.top - pad.bottom;
	const min = Math.min(...points.map((point) => point.value), 0);
	const max = Math.max(...points.map((point) => point.value), 0);
	const range = Math.max(max - min, 1);
	const x = (index: number) =>
		pad.left +
		(points.length === 1
			? innerWidth / 2
			: (index / (points.length - 1)) * innerWidth);
	const y = (value: number) => pad.top + ((max - value) / range) * innerHeight;
	const zeroY = y(0);
	const line = points
		.map((point, index) => `${x(index)},${y(point.value)}`)
		.join(" ");
	return (
		<div className="overflow-x-auto">
			<svg
				viewBox={`0 0 ${width} ${chartHeight}`}
				className="min-w-[28rem] w-full"
				role="img"
				aria-label={`${humanize(kind)} chart`}
			>
				<title>{`${humanize(kind)} chart`}</title>
				<line
					x1={pad.left}
					y1={pad.top}
					x2={pad.left}
					y2={pad.top + innerHeight}
					stroke="currentColor"
					opacity="0.2"
				/>
				<line
					x1={pad.left}
					y1={zeroY}
					x2={width - pad.right}
					y2={zeroY}
					stroke="currentColor"
					opacity="0.2"
				/>
				{kind === "bar"
					? points.map((point, index) => {
							const barWidth = Math.max(8, innerWidth / points.length - 8);
							return (
								<rect
									key={point.key}
									x={pad.left + (index * innerWidth) / points.length + 4}
									y={Math.min(y(point.value), zeroY)}
									width={barWidth}
									height={Math.abs(zeroY - y(point.value))}
									fill={CHART_COLORS[0]}
								>
									<title>{`${point.label}: ${point.value}`}</title>
								</rect>
							);
						})
					: null}
				{kind === "area" ? (
					<polygon
						points={`${pad.left},${zeroY} ${line} ${width - pad.right},${zeroY}`}
						fill={CHART_COLORS[0]}
						opacity="0.2"
					/>
				) : null}
				{kind !== "bar" ? (
					<polyline
						points={line}
						fill="none"
						stroke={CHART_COLORS[0]}
						strokeWidth="3"
					/>
				) : null}
				{points.map((point, index) => (
					<g key={`label:${point.key}`}>
						<text
							x={
								kind === "bar"
									? pad.left + ((index + 0.5) * innerWidth) / points.length
									: x(index)

--- rest relevant ---
									: x(index)
							}
							y={chartHeight - 16}
							textAnchor="middle"
							fontSize="11"
							fill="currentColor"
						>
							{point.label.slice(0, 12)}
						</text>
						{kind !== "bar" ? (
							<circle
								cx={x(index)}
								cy={y(point.value)}
								r="3"
								fill={CHART_COLORS[0]}
							>
								<title>{`${point.label}: ${point.value}`}</title>
							</circle>
						) : null}
					</g>
				))}
				{xLabel ? (
					<text
						x={pad.left + innerWidth / 2}
						y={chartHeight - 2}
						textAnchor="middle"
						fontSize="10"
						fill="currentColor"
					>
						{xLabel}
					</text>
				) : null}
				{yLabel ? (
					<text
						x="11"
						y={pad.top + innerHeight / 2}
						textAnchor="middle"
						fontSize="10"
						fill="currentColor"
						transform={`rotate(-90 11 ${pad.top + innerHeight / 2})`}
					>
						{yLabel}
					</text>
				) : null}
			</svg>
		</div>
	);
};

const PieChart: FC<{
	data: unknown;
	nameField?: string;
	valueField?: string;
	height?: number;
	showLabel?: boolean;
	showLegend?: boolean;
	radius?: string | [string, string];
	highlightName?: string | null;
}> = ({
	data,
	nameField = "name",
	valueField = "value",
	height,
	showLabel = true,
	showLegend = true,
	radius = ["50%", "70%"],
	highlightName = null,
}) => {
	const points = normalizePoints(data, nameField, valueField).filter(
		(point) => point.value > 0,
	);
	if (points.length === 0)
		return <p className="text-muted-foreground text-xs">No chart data.</p>;
	const total = points.reduce((sum, point) => sum + point.value, 0);
	const size = Math.max(140, Number(height) || 400);
	const center = size / 2;
	const radiusValue = Array.isArray(radius) ? radius : ["0%", radius];
	const parseRadius = (value: string | undefined, fallback: number): number => {
		if (!value) return fallback;
		if (value.endsWith("%")) {
			const percentage = Number(value.slice(0, -1));
			return Number.isFinite(percentage)
				? (Math.max(0, Math.min(100, percentage)) / 100) * (center - 12)
				: fallback;
		}
		const numeric = Number(value);
		return Number.isFinite(numeric) ? Math.max(0, numeric) : fallback;
	};
	const innerRadius = parseRadius(String(radiusValue[0] ?? "0%"), 0);
	const outerRadius = Math.max(
		innerRadius + 1,
		parseRadius(String(radiusValue[1] ?? "70%"), center - 12),
	);
	const sourceItems = Array.isArray(data) ? data : [];
	const segmentPath = (start: number, end: number): string => {
		const safeEnd = end - start >= Math.PI * 2 ? end - 0.00001 : end;
		const outerStart = [
			center + outerRadius * Math.cos(start),
			center + outerRadius * Math.sin(start),
		];
		const outerEnd = [
			center + outerRadius * Math.cos(safeEnd),
			center + outerRadius * Math.sin(safeEnd),
		];
		const large = safeEnd - start > Math.PI ? 1 : 0;
		if (innerRadius <= 0) {
			return `M ${center} ${center} L ${outerStart[0]} ${outerStart[1]} A ${outerRadius} ${outerRadius} 0 ${large} 1 ${outerEnd[0]} ${outerEnd[1]} Z`;
		}
		const innerEnd = [
			center + innerRadius * Math.cos(safeEnd),
			center + innerRadius * Math.sin(safeEnd),
		];
		const innerStart = [
			center + innerRadius * Math.cos(start),
			center + innerRadius * Math.sin(start),
		];
		return `M ${outerStart[0]} ${outerStart[1]} A ${outerRadius} ${outerRadius} 0 ${large} 1 ${outerEnd[0]} ${outerEnd[1]} L ${innerEnd[0]} ${innerEnd[1]} A ${innerRadius} ${innerRadius} 0 ${large} 0 ${innerStart[0]} ${innerStart[1]} Z`;
	};
	let nextAngle = -Math.PI / 2;
	const segments = points.map((point, index) => {
		const start = nextAngle;
		nextAngle += (point.value / total) * Math.PI * 2;
		const item =
			sourceItems.find(
				(candidate) =>
					isRecord(candidate) &&
					String(candidate[nameField] ?? candidate.name ?? "") === point.label,
			) ?? sourceItems[index];
		const sourceItem = isRecord(item) ? item : null;
		const itemStyle =
			sourceItem && isRecord(sourceItem.itemStyle)
				? sourceItem.itemStyle
				: null;
		return {
			...point,
			color:
				typeof itemStyle?.color === "string"
					? itemStyle.color
					: CHART_COLORS[index % CHART_COLORS.length],
			end: nextAngle,
			opacity: highlightName && point.label !== highlightName ? 0.3 : 1,
			start,
		};
	});
	return (
		<div className="flex flex-wrap items-center gap-3">
			<svg
				viewBox={`0 0 ${size} ${size}`}
				width={size}
				height={size}
				className="max-w-full"
				role="img"
				aria-label="Pie chart"
			>
				<title>Pie chart</title>
				{segments.map((segment) => {
					const mid = segment.start + (segment.end - segment.start) / 2;
					const labelRadius = outerRadius + 12;
					return (
						<g key={segment.key}>
							<path
								d={segmentPath(segment.start, segment.end)}
								fill={segment.color}
								opacity={segment.opacity}
							>
								<title>{`${segment.label}: ${segment.value}`}</title>
							</path>
							{showLabel ? (
								<text
									x={center + labelRadius * Math.cos(mid)}
									y={center + labelRadius * Math.sin(mid)}
									textAnchor="middle"
									fontSize="10"
									fill="currentColor"
								>
									{segment.label}: {Math.round((segment.value / total) * 100)}%
								</text>
							) : null}
						</g>
					);
				})}
			</svg>
			{showLegend ? (
				<ul className="space-y-1 text-xs">
					{segments.map((segment) => (
						<li
							key={`${segment.key}:legend`}
							className="flex items-center gap-1.5"
						>
							<span
								className="h-2.5 w-2.5 rounded-sm"
								style={{
									backgroundColor: segment.color,
									opacity: segment.opacity,
								}}
							/>
							{segment.label}: {segment.value}
						</li>
					))}
				</ul>
			) : null}
		</div>
	);
};

const Sparkline: FC<{
	data: unknown;
	color?: string;
	width?: number;
	height?: number;
	trend?: "up" | "down" | "stable";
}> = ({ data, color = CHART_COLORS[0], width = 100, height = 40, trend }) => {
	const lineColor =
		trend === "up" ? "#ef4444" : trend === "down" ? "#22c55e" : color;
	const values = Array.isArray(data)
		? data.map(Number).filter(Number.isFinite)
		: [];
	if (values.length === 0) values.push(0);
	const max = Math.max(...values);
	const min = Math.min(...values);
	const range = Math.max(max - min, 1);
	const points = values
		.map(
			(value, index) =>
				`${values.length > 1 ? (index / (values.length - 1)) * width : width / 2},${height - ((value - min) / range) * (height - 4) - 2}`,
		)
		.join(" ");
	const areaPoints = `${points} ${width},${height} 0,${height}`;
	return (
		<svg
			width={width}
			height={height}
			viewBox={`0 0 ${width} ${height}`}
			className="max-w-full overflow-visible"
			role="img"
			aria-label="Sparkline"
		>
			<title>Sparkline</title>
			<polygon points={areaPoints} fill={lineColor} fillOpacity="0.12" />
			<polyline
				points={points}
				fill="none"
				stroke={lineColor}
				strokeWidth="2"
				strokeLinecap="round"
				strokeLinejoin="round"
			/>
		</svg>
	);
};

const StackedAreaChart: FC<{
	data: unknown;
	series: unknown;
	height?: number;
	xLabel?: string;
	yLabel?: string;
	onSeriesClick?: (seriesKey: string) => unknown;
	onDateRangeSelect?: (start: string, end: string) => unknown;
}> = ({
	data,
	series,
	height,
	xLabel,
	yLabel,
	onSeriesClick,
	onDateRangeSelect,
}) => {
	const [rangeStart, setRangeStart] = useState(0);
	const [rangeEnd, setRangeEnd] = useState(100);
	const rows = Array.isArray(data) ? data.filter(isRecord) : [];
	const entries = Array.isArray(series)
		? series.filter(isRecord).map((item, index) => ({
				color: String(item.color ?? seriesColor(String(item.key ?? ""), index)),
				key: String(item.key ?? `series_${index + 1}`),
				name: String(item.name ?? item.key ?? `Series ${index + 1}`),
			}))
		: [];
	if (rows.length === 0 || entries.length === 0)
		return <p className="text-muted-foreground text-xs">No chart data.</p>;

	const width = 600;
	const chartHeight = Math.max(140, Number(height) || 180);
	const pad = { left: 44, right: 14, top: 14, bottom: 38 };
	const innerWidth = width - pad.left - pad.right;
	const innerHeight = chartHeight - pad.top - pad.bottom;
	const totals = rows.map((row) =>
		entries.reduce(
			(sum, entry) => sum + Math.max(0, Number(row[entry.key]) || 0),
			0,
		),
	);
	const max = Math.max(...totals, 1);
	const x = (index: number) =>
		pad.left +
		(rows.length === 1
			? innerWidth / 2
			: (index / (rows.length - 1)) * innerWidth);
	const y = (value: number) =>
		pad.top + innerHeight - (value / max) * innerHeight;
	let lower = rows.map(() => 0);
	const layers = entries.map((entry) => {
		const upper = lower.map(
			(base, index) => base + Math.max(0, Number(rows[index][entry.key]) || 0),
		);
		const points = [
			...upper.map((value, index) => `${x(index)},${y(value)}`),
			...lower.map((value, index) => `${x(index)},${y(value)}`).reverse(),
		].join(" ");
		lower = upper;
		return { ...entry, points };
	});
	const dateLabel = (row: UnknownRecord, index: number): string => {
		const raw = String(row.date ?? row.label ?? index + 1);
		const parsed = new Date(raw);
		return Number.isNaN(parsed.getTime())
			? raw.slice(0, 12)
			: `${parsed.getMonth() + 1}/${parsed.getDate()}`;
	};
	const emitRange = (start: number, end: number) => {
		if (!onDateRangeSelect || rows.length === 0) return;
		const startIndex = Math.floor((start / 100) * rows.length);
		const endIndex = Math.min(
			rows.length - 1,
			Math.max(startIndex, Math.ceil((end / 100) * rows.length) - 1),
		);
		const startDate = rows[startIndex]?.date;
		const endDate = rows[endIndex]?.date;
		if (typeof startDate === "string" && typeof endDate === "string") {
			onDateRangeSelect(startDate, endDate);
		}
	};

	return (
		<div className="space-y-2">
			<div className="overflow-x-auto">
				<svg
					viewBox={`0 0 ${width} ${chartHeight}`}
					className="min-w-[28rem] w-full"
					role="img"
					aria-label="Stacked area chart"
				>
					<title>Stacked area chart</title>
					<line
						x1={pad.left}
						y1={pad.top + innerHeight}
						x2={width - pad.right}
						y2={pad.top + innerHeight}
						stroke="currentColor"
						opacity="0.2"
					/>
					{layers.map((layer) => (
						<polygon
							key={layer.key}
							points={layer.points}
							fill={layer.color}
							opacity="0.65"
						>
							<title>{layer.name}</title>
						</polygon>
					))}
					{rows.map((row, index) => (
						<text
							// biome-ignore lint/suspicious/noArrayIndexKey: time-series rows may repeat labels and are immutable here.
							key={`${String(row.date ?? row.label ?? "point")}:${index}`}
							x={x(index)}
							y={chartHeight - 16}
							textAnchor="middle"
							fontSize="11"
							fill="currentColor"
						>
							{dateLabel(row, index)}
						</text>
					))}
					{xLabel ? (
						<text
							x={pad.left + innerWidth / 2}
							y={chartHeight - 2}
							textAnchor="middle"
							fontSize="10"
							fill="currentColor"
						>
							{xLabel}
						</text>
					) : null}
					{yLabel ? (
						<text
							x="11"
							y={pad.top + innerHeight / 2}
							textAnchor="middle"
							fontSize="10"
							fill="currentColor"
							transform={`rotate(-90 11 ${pad.top + innerHeight / 2})`}
						>
							{yLabel}
						</text>
					) : null}
				</svg>
			</div>
			<div className="flex flex-wrap gap-2 text-xs">
				{entries.map((entry) => (
					<button
						key={entry.key}
						type="button"
						className="inline-flex items-center gap-1.5"
						onClick={onSeriesClick ? () => onSeriesClick(entry.key) : undefined}
					>
						<span
							className="h-2.5 w-2.5 rounded-sm"
							style={{ backgroundColor: entry.color }}
						/>
						{entry.name}
					</button>
				))}
			</div>
			{onDateRangeSelect ? (
				<div className="grid grid-cols-2 gap-3 text-xs">
					<label>
						<span className="text-muted-foreground">Range start</span>
						<input
							type="range"
							min="0"
							max="100"
							value={rangeStart}
							className="block w-full"
							onChange={(event) => {
								const next = Math.min(
									Number(event.currentTarget.value),
									rangeEnd,
								);
								setRangeStart(next);
								emitRange(next, rangeEnd);
							}}
						/>
					</label>
					<label>
						<span className="text-muted-foreground">Range end</span>
						<input
							type="range"
							min="0"
							max="100"
							value={rangeEnd}
							className="block w-full"
							onChange={(event) => {
								const next = Math.max(
									Number(event.currentTarget.value),
									rangeStart,
								);
								setRangeEnd(next);
								emitRange(rangeStart, next);
							}}
						/>
					</label>
				</div>
			) : null}
		</div>
	);
};

