function renderNode(
	node: McpJsonNode,
	context: RenderContext,
	key?: string | number,
): ReactNode {
	if (!isRecord(node) || typeof node.type !== "string") return null;
	if (node.type === "text")
		return typeof node.content === "string" ? node.content : null;
	if (node.type === "data") {
		const value = getValueByPath(context.data, String(node.path ?? ""));
		const resolved = value === undefined ? node.fallback : value;
		return formatValue(resolved, node.format as ValueFormat | undefined);
	}
	if (node.type === "if") {
		const branch = getValueByPath(context.data, String(node.condition ?? ""))
			? node.then
			: node.else;
		return isRecord(branch)
			? renderNode(branch as McpJsonNode, context, key)
			: null;
	}
	if (node.type === "each") {
		const items = getValueByPath(context.data, String(node.items ?? ""));
		if (!Array.isArray(items)) return null;
		return items.map((item, index) => {
			const as = String(node.as ?? "item");
			const itemContext = {
				...context,
				data: { ...context.data, [as]: item, [`${as}Index`]: index },
			};
			if (typeof node.render === "string") {
				return (
					// biome-ignore lint/suspicious/noArrayIndexKey: template loop items may be duplicate, identity-less values and are immutable here.
					<span key={`${as}:${index}`}>
						{node.render.replaceAll(
							`{{${as}}}`,
							typeof item === "string" ? item : stringify(item),
						)}
					</span>
				);
			}
			return isRecord(node.render)
				? renderNode(node.render as McpJsonNode, itemContext, index)
				: null;
		});
	}

	const props = resolvedProps(node, context);
	const children = Array.isArray(node.children)
		? node.children.map((child, index) => renderNode(child, context, index))
		: undefined;
	const className =
		typeof props.className === "string" ? props.className : undefined;

	const htmlTags = new Set([
		"div",
		"span",
		"p",
		"h1",
		"h2",
		"h3",
		"h4",
		"ul",
		"ol",
		"li",
		"thead",
		"tbody",
		"tr",
		"th",
		"td",
	]);
	if (htmlTags.has(node.type))
		return createElement(node.type, { key, ...domProps(props) }, children);

	switch (node.type) {
		case "card":
			return (
				<section
					key={key}
					className={cn(FILLED_BOX, "overflow-hidden", className)}
				>
					{children}
				</section>
			);
		case "card-header":
			return (
				<header
					key={key}
					className={cn("space-y-1.5 border-border/70 border-b p-3", className)}
				>
					{children}
				</header>
			);
		case "card-title":
			return (
				<h3 key={key} className={cn("font-semibold text-base", className)}>
					{children}
				</h3>
			);
		case "card-description":
			return (
				<p key={key} className={cn("text-muted-foreground text-sm", className)}>
					{children}
				</p>
			);
		case "card-content":
			return (
				<div key={key} className={cn("space-y-2 p-3", className)}>
					{children}
				</div>
			);
		case "badge":
			return (
				<span
					key={key}
					className={cn(
						"inline-flex rounded-full border border-border px-2 py-0.5 font-medium text-xs",
						className,
					)}
				>
					{children}
				</span>
			);
		case "button":
			return (
				<button
					key={key}
					type="button"
					className={cn(
						"inline-flex h-9 items-center justify-center rounded-md bg-primary px-3 font-medium text-primary-foreground text-sm",
						className,
					)}
					{...(domProps(props) as { onClick?: () => void })}
				>
					{children}
				</button>
			);
		case "alert":
			return (
				<div
					key={key}
					role="alert"
					className={cn(
						"rounded-md border border-border p-3",
						props.variant === "destructive" &&
							"border-destructive/50 text-destructive",
						className,
					)}
				>
					{children}
				</div>
			);
		case "alert-title":
			return (
				<h4 key={key} className={cn("font-medium text-sm", className)}>
					{children}
				</h4>
			);
		case "alert-description":
			return (
				<div key={key} className={cn("mt-1 text-sm", className)}>
					{children}
				</div>
			);
		case "progress": {
			const value = Math.max(0, Math.min(100, Number(props.value) || 0));
			return (
				<div key={key} className={cn("flex items-center gap-2", className)}>
					<div className="h-3 flex-1 overflow-hidden rounded-full bg-secondary">
						<div className="h-full bg-primary" style={{ width: `${value}%` }} />
					</div>
					<span className="text-muted-foreground text-xs">
						{String(props.label ?? `${Math.round(value)}%`)}
					</span>
				</div>
			);
		}
		case "separator":
			return <hr key={key} className={cn("border-border", className)} />;
		case "markdown":
			return (
				<div key={key} className={cn("text-sm", className)}>
					<McpMarkdownText
						text={String(props.content ?? "")}
						openLink={context.openLink}
					/>
				</div>
			);
		case "layout":
			return (
				<div
					key={key}
					className={cn(
						"flex gap-3",
						props.direction === "horizontal" ? "flex-row" : "flex-col",
						className,
					)}
				>
					{children}
				</div>
			);
		case "columns": {
			const count = Math.max(1, node.children?.length ?? 1);
			return (
				<div
					key={key}
					className={cn("grid gap-3", className)}
					style={{ gridTemplateColumns: `repeat(${count}, minmax(0, 1fr))` }}
				>
					{children}
				</div>
			);
		}
		case "metric":
			return (
				<div key={key} className={cn(FILLED_BOX, "p-3", className)}>
					<p className="text-muted-foreground text-xs">
						{String(props.label ?? "")}
					</p>
					<p className="mt-1 font-bold text-2xl">{String(props.value ?? "")}</p>
				</div>
			);
		case "table":
			return Array.isArray(props.data) ? (
				<TableView
					key={key}
					data={props.data}
					columns={props.columns}
					title={props.title}
					context={context}
				/>
			) : (
				<table
					key={key}
					className={cn("w-full border-collapse text-xs", className)}
				>
					{children}
				</table>
			);
		case "bar-chart":
		case "line-chart":
		case "area-chart":
			return (
				<CartesianChart
					key={key}
					kind={node.type.replace("-chart", "") as "bar" | "line" | "area"}
					data={props.data}
					labelField={props.labelField as string | undefined}
					valueField={props.valueField as string | undefined}
					xLabel={props.xLabel as string | undefined}
					yLabel={props.yLabel as string | undefined}
					height={props.height as number | undefined}
				/>
			);
		case "pie-chart":
			return (
				<PieChart
					key={key}
					data={props.data}
					nameField={props.nameField as string | undefined}
					valueField={props.valueField as string | undefined}
					height={props.height as number | undefined}
					showLabel={props.showLabel as boolean | undefined}
					showLegend={props.showLegend as boolean | undefined}
					radius={props.radius as string | [string, string] | undefined}
					highlightName={props.highlightName as string | null | undefined}
				/>
			);
		case "sparkline":
			return (
				<Sparkline
					key={key}
					data={props.data}
					color={props.color as string | undefined}
					width={props.width as number | undefined}
					height={props.height as number | undefined}
					trend={props.trend as "up" | "down" | "stable" | undefined}
				/>
			);
		case "stacked-area-chart":
			return (
				<StackedAreaChart
					key={key}
					data={props.data}
					series={props.series}
					height={props.height as number | undefined}
					xLabel={props.xLabel as string | undefined}
					yLabel={props.yLabel as string | undefined}
					onSeriesClick={
